import unittest
from compiler.optimizer import optimize_ast

class TestOptimizer(unittest.TestCase):
    def test_constant_fold(self):
        code = "x = 2 + 3 * 4"
        opt = optimize_ast(code)
        self.assertEqual(opt, "x = 14")

if __name__ == '__main__': unittest.main()
